using AITokenUsageWidget.Shared.Models;

namespace AITokenUsageWidget.Shared.Widgets;

/// <summary>
/// 品牌图标 PNG（与主 App ProviderChip 同图形，离线由 96×96 原图双三次重采样生成）。
/// Board 不渲染 data: URI 图片，图标由 Provider 内嵌的本地 HTTP 图片服务以
/// http://127.0.0.1 URL 提供；按显示尺寸预生成（18px/14px），保证固有尺寸 ==
/// 声明尺寸——无论 Board 是否支持像素尺寸声明都不会被裁剪或模糊。
/// </summary>
public static class BrandIcons
{
    public static byte[] Png(ProviderKind kind, int size) => Convert.FromBase64String(
        (kind, size) switch
        {
            (ProviderKind.DeepSeek, 18) => DeepSeek18,
            (ProviderKind.DeepSeek, _) => DeepSeek14,
            (ProviderKind.Kimi, 18) => Kimi18,
            (ProviderKind.Kimi, _) => Kimi14,
            (_, 18) => Glm18,
            (_, _) => Glm14,
        });

    private const string DeepSeek18 = "";
    private const string DeepSeek14 = "";
    private const string Kimi18 = "";
    private const string Kimi14 = "";
    private const string Glm18 = "";
    private const string Glm14 = "";
}
